ument.getElementById('kbSearch'),cards=[...document.querySelectorAll('.card')];q.addEventListener('input',()=>{const v=q.value.toLowerCase().trim();cards.forEach(c=>c.hidden=!!v&&!c.dataset.search.includes(v))});</script></body></html>
